{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1720;--card:#071022;--accent:#9ad3c7;--muted:#9aa8b2;--glass:rgba(255,255,255,0.04);--glass-2:rgba(255,255,255,0.02)}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:#e6eef0;background:linear-gradient(180deg,var(--bg),#041018);}
    header{position:relative;padding:28px 32px;display:flex;align-items:center;justify-content:space-between}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:48px;height:48px;background:linear-gradient(135deg,#083743 0%,#0b6a58 100%);border-radius:10px;display:grid;place-items:center;color:#e6fff7;font-weight:700}
    nav a{color:var(--muted);text-decoration:none;margin-left:18px;font-size:15px}
    nav a:hover{color:var(--accent)}
    .hero{padding:44px 32px 28px;display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:start}
    .hero-card{background:linear-gradient(180deg,var(--glass),var(--glass-2));padding:28px;border-radius:14px;box-shadow:0 6px 30px rgba(3,10,12,0.6);backdrop-filter:blur(6px)}
    h1{margin:0 0 8px;font-weight:600;color:#f2faf8;font-size:28px}
    p.lead{margin:0;color:var(--muted);line-height:1.45}
    .pattern{position:absolute;inset:0;opacity:0.06;background-image:url('assets/img/pattern.svg');background-repeat:repeat;mix-blend-mode:screen}

    /* Pricing comparator */
    .comparator{margin-top:18px;padding:18px;border-radius:12px;background:#061b23;color:#dff7ef}
    .toggle{display:flex;gap:8px;align-items:center}
    .toggle button{background:transparent;border:1px solid rgba(255,255,255,0.06);padding:8px 12px;border-radius:10px;color:var(--muted);cursor:pointer}
    .toggle button.active{background:linear-gradient(90deg,#0b6a58,#0b8e70);color:#04251b;border:0}
    .plans{display:flex;gap:12px;margin-top:14px}
    .plan{flex:1;background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));padding:14px;border-radius:10px}
    .plan h3{margin:0 0 6px;font-size:15px;color:#eafff6}
    .price{font-size:20px;font-weight:700;color:var(--accent)}
    .meta{font-size:12px;color:var(--muted);margin-top:6px}

    /* Proof gallery */
    .proof{margin-top:22px}
    .proof .viewer{height:120px;background:linear-gradient(180deg,#02121a,rgba(2,10,12,0.3));padding:14px;border-radius:10px;display:flex;flex-direction:column;justify-content:center}
    .quote{font-size:14px;color:#dff7ef;margin:0}
    .attrib{font-size:12px;color:var(--muted);margin-top:8px}
    .badges{display:flex;gap:10px;margin-top:12px}
    .badge{background:transparent;border-radius:8px;padding:8px 10px;color:var(--muted);border:1px solid rgba(255,255,255,0.03);cursor:default;position:relative}
    .badge:hover::after{content:attr(data-tooltip);position:absolute;bottom:calc(100% + 8px);left:50%;transform:translateX(-50%);background:#081b22;padding:8px;border-radius:6px;color:#bfe7de;font-size:12px;white-space:nowrap;box-shadow:0 6px 18px rgba(0,0,0,0.6)}

    footer{padding:22px 32px;color:var(--muted);display:flex;justify-content:space-between;align-items:center}
    .cta{background:linear-gradient(90deg,#0b6a58,#0b8e70);color:#04251b;border:0;padding:10px 14px;border-radius:10px;text-decoration:none}

    @media(max-width:880px){.hero{grid-template-columns:1fr;}.brand .logo{width:40px;height:40px}}
  </style>
</head>
<body>
  <div class="pattern" aria-hidden="true"></div>
  <header>
    <div class="brand">
      <div class="logo">HM</div>
      <div>
        <div style="font-weight:700;color:#dff7ef">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav aria-label="Main navigation">
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="conditions.html">Ailments</a>
      <a href="approach.html">Path</a>
      <a href="pricing.html">Invest</a>
      <a href="about.html">About</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main>
    <section class="hero" aria-labelledby="hero-title">
      <div class="hero-card">
        <h1 id="hero-title">A practical suite of whole-person offerings</h1>
        <p class="lead">Focused sessions and curated packages to help you move from overwhelm to steadier days. Short courses, diagnostics, and pathway plans designed to match a busy life.</p>

        <div class="comparator" aria-hidden="false">
          <div style="display:flex;justify-content:space-between;align-items:center">
            <strong>Choose pricing view</strong>
            <div class="toggle" role="tablist" aria-label="Pricing toggle">
              <button id="opt-monthly" class="active" aria-pressed="true">Monthly</button>
              <button id="opt-package" aria-pressed="false">Package</button>
            </div>
          </div>

          <div class="plans" aria-live="polite">
            <div class="plan">
              <h3>Seed — Foundations</h3>
              <div class="price" data-month="99" data-package="499">$<span class="num">99</span></div>
              <div class="meta">4 sessions + plan overview</div>
            </div>
            <div class="plan">
              <h3>Root — Momentum</h3>
              <div class="price" data-month="175" data-package="899">$<span class="num">175</span></div>
              <div class="meta">8 sessions + tracking & labs</div>
            </div>
            <div class="plan">
              <h3>Canopy — Support</h3>
              <div class="price" data-month="320" data-package="1599">$<span class="num">320</span></div>
              <div class="meta">12 sessions + full pathway</div>
            </div>
          </div>
        </div>

        <div class="proof">
          <div class="viewer" role="status" aria-live="polite">
            <p class="quote" id="testimonial-text">"I found practical, steady tools that fit my schedule and improved my energy over weeks."</p>
            <div class="attrib" id="testimonial-by">— A. Rivera, teacher</div>
          </div>

          <div class="badges" aria-hidden="false">
            <div class="badge" data-tooltip="Peer-reviewed study collaborator">Research Partner</div>
            <div class="badge" data-tooltip="Featured in local health magazine">Local Feature</div>
            <div class="badge" data-tooltip="Certified clinical and holistic credentials">Credentials</div>
          </div>
        </div>

      </div>

      <aside class="hero-card" aria-labelledby="side-title">
        <h2 id="side-title" style="margin-top:0;color:#dff7ef">Tailored tracks</h2>
        <p style="color:var(--muted)">Pick a focused track to begin: Reset Rhythm, Digestive Balance, Stress Mapping. Each track includes a planner and two guided touchpoints.</p>
        <div style="margin-top:14px">
          <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        </div>
      </aside>
    </section>

    <section style="padding:28px 32px 12px">
      <div class="hero-card">
        <h3 style="margin:0 0 10px;color:#eafff6">Why people choose this approach</h3>
        <ul style="color:var(--muted);margin:0 0 0 18px">
          <li>Actionable steps you can use between sessions.</li>
          <li>Measurements that inform next steps — not just ideas.</li>
          <li>Collaboration with you, your timeline and preferences.</li>
        </ul>
      </div>
    </section>

  </main>

  <footer>
    <div>
      <div style="font-weight:600;color:#dff7ef">Contact</div>
      <div style="font-size:13px;color:var(--muted)">Phone: {{PHONE}} • <a href="mailto:{{EMAIL}}" style="color:var(--muted);text-decoration:underline">{{EMAIL}}</a></div>
    </div>
    <div>
      <small style="color:var(--muted)">Serving {{CITY}}, {{STATE}}</small>
    </div>
  </footer>

  <script>
    // Pricing comparator logic with animated numbers
    (function(){
      function animateNumber(el, start, end, duration){
        let startTime = null;
        const step = (ts)=>{
          if(!startTime) startTime = ts;
          const progress = Math.min((ts - startTime)/duration,1);
          const value = Math.round(start + (end - start) * progress);
          el.textContent = value;
          if(progress < 1) requestAnimationFrame(step);
        };
        requestAnimationFrame(step);
      }

      const monthlyBtn = document.getElementById('opt-monthly');
      const packageBtn = document.getElementById('opt-package');
      const priceEls = document.querySelectorAll('.price');
      const nums = document.querySelectorAll('.price .num');

      function setMode(mode){
        const active = mode === 'monthly';
        monthlyBtn.classList.toggle('active', active);
        packageBtn.classList.toggle('active', !active);
        monthlyBtn.setAttribute('aria-pressed', active);
        packageBtn.setAttribute('aria-pressed', !active);
        priceEls.forEach((pe,i)=>{
          const target = parseInt(pe.getAttribute(active? 'data-month':'data-package'),10);
          const current = parseInt(nums[i].textContent,10) || 0;
          animateNumber(nums[i], current, target, 600);
        });
      }

      monthlyBtn.addEventListener('click',()=> setMode('monthly'));
      packageBtn.addEventListener('click',()=> setMode('package'));

      // initialize
      setMode('monthly');
    })();

    // Proof gallery rotator
    (function(){
      const items = [
        {text:'"I found practical, steady tools that fit my schedule and improved my energy over weeks."', by:'— A. Rivera, teacher'},
        {text:'"Clear steps, measured results — the plan worked alongside my job and family."', by:'— M. Chen, designer'},
        {text:'"Gentle but focused. It wasn\'t a rush; it was steady changes that stuck."', by:'— K. Alvarez, nurse'}
      ];
      let idx = 0;
      const tText = document.getElementById('testimonial-text');
      const tBy = document.getElementById('testimonial-by');
      function rotate(){
        idx = (idx + 1) % items.length;
        tText.style.opacity = 0; tBy.style.opacity = 0;
        setTimeout(()=>{
          tText.textContent = items[idx].text;
          tBy.textContent = items[idx].by;
          tText.style.opacity = 1; tBy.style.opacity = 1;
        },300);
      }
      setInterval(rotate,5000);
    })();
  </script>
</body>
</html>"} 
