{"path":"approach.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Path & Method — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#041018;--card:#072126;--accent:#baf3df;--muted:#94b0ac}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;color:#e8f7f2;background:linear-gradient(180deg,var(--bg),#021018)}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px}
    nav a{color:var(--muted);text-decoration:none;margin-left:14px}
    .mast{padding:28px 24px;display:grid;grid-template-columns:1fr 320px;gap:18px}
    .card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:16px;border-radius:12px}
    h1{margin:0 0 6px;color:#e8f7f4}
    .mythgrid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px}
    .myth{padding:12px;border-radius:10px;background:rgba(255,255,255,0.01)}
    .pillars{display:flex;gap:10px;margin-top:16px}
    .pillar{flex:1;padding:12px;border-radius:10px;background:rgba(255,255,255,0.01)}
    .cta{display:inline-block;margin-top:12px;padding:8px 12px;background:#0b7b59;color:#07261a;border-radius:8px;text-decoration:none}
    @media(max-width:880px){.mast{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:700;color:#dff7ef">How we work</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="approach.html">Path</a>
      <a href="services.html">Offerings</a>
      <a href="pricing.html">Invest</a>
      <a href="about.html">About</a>
      <a href="book.html">Book</a>
    </nav>
  </header>

  <main>
    <section class="mast">
      <div class="card" aria-labelledby="approach-title">
        <h1 id="approach-title">A stepwise map for complex lives</h1>
        <p style="color:var(--muted)">We prioritize readable steps and measurable shifts. Each plan is built to fit daily obligations while tracking what changes matter most.</p>

        <div class="mythgrid" aria-hidden="false">
          <div class="myth">
            <strong>Myth</strong>
            <p style="color:var(--muted)">Holistic care means long, vague programs that demand big life changes.</p>
          </div>
          <div class="myth">
            <strong>Truth</strong>
            <p style="color:var(--muted)">We favor short, methodical steps and measurable trials so you can see what helps without disruption.</p>
          </div>
          <div class="myth">
            <strong>Myth</strong>
            <p style="color:var(--muted)">You have to stop everything to get better.</p>
          </div>
          <div class="myth">
            <strong>Truth</strong>
            <p style="color:var(--muted)">Change is often incremental; we design shifts that slot into your existing life.
            </p>
          </div>
        </div>

        <div class="pillars" role="list">
          <div class="pillar" role="listitem">
            <strong>Measure</strong>
            <div style="color:var(--muted);margin-top:6px">Start with a few useful data points so decisions are guided by what changes.</div>
          </div>
          <div class="pillar" role="listitem">
            <strong>Trial</strong>
            <div style="color:var(--muted);margin-top:6px">Small experiments with clear duration and review points.</div>
          </div>
          <div class="pillar" role="listitem">
            <strong>Adjust</strong>
            <div style="color:var(--muted);margin-top:6px">Keep what works, refine what doesn\'t.</div>
          </div>
        </div>

        <a class="cta" href="{{PRIMARY_CTA_URL}}">Begin a short pathway</a>
      </div>

      <aside class="card" aria-labelledby="side-title">
        <h3 id="side-title" style="margin-top:0;color:#dff7ef">Snapshot: The Intake</h3>
        <p style="color:var(--muted)">A focused 60–75 minute conversation, symptom map, and a 2-week trial plan to test early changes.</p>

        <div style="margin-top:12px">
          <strong style="color:#e6faf4">What you get</strong>
          <ul style="color:var(--muted);margin:8px 0 0 18px">
            <li>Listening intake</li>
            <li>Two practical actions to try</li>
            <li>Follow-up touchpoint</li>
          </ul>
        </div>

        <div style="margin-top:12px">
          <a class="cta" href="book.html">Schedule intake</a>
        </div>
      </aside>
    </section>

    <section style="padding:18px 24px">
      <div class="card">
        <h3 style="margin:0 0 10px;color:#eafff6">Compare simple plans</h3>
        <p style="color:var(--muted);margin:0 0 12px">A micro-comparator to see monthly vs package frames for alignment and budgeting.</p>

        <div style="display:flex;gap:10px;align-items:center">
          <label style="color:var(--muted)">View:</label>
          <button id="view-month" style="padding:8px;border-radius:8px;border:1px solid rgba(255,255,255,0.03);background:#072126;color:#cfeee0">Monthly</button>
          <button id="view-package" style="padding:8px;border-radius:8px;border:1px solid rgba(255,255,255,0.03);background:transparent;color:var(--muted)">Package</button>
        </div>

        <div style="display:flex;gap:10px;margin-top:12px">
          <div style="flex:1;padding:10px;border-radius:8px;background:rgba(255,255,255,0.01)">
            <div style="color:#dff7ef;font-weight:700">Starter</div>
            <div style="font-size:20px;color:var(--accent)">$<span class="anim" data-month="75" data-package="365">75</span></div>
            <div style="color:var(--muted)">Two sessions + plan</div>
          </div>
          <div style="flex:1;padding:10px;border-radius:8px;background:rgba(255,255,255,0.01)">
            <div style="color:#dff7ef;font-weight:700">Core</div>
            <div style="font-size:20px;color:var(--accent)">$<span class="anim" data-month="150" data-package="749">150</span></div>
            <div style="color:var(--muted)">Follow ups + review</div>
          </div>
          <div style="flex:1;padding:10px;border-radius:8px;background:rgba(255,255,255,0.01)">
            <div style="color:#dff7ef;font-weight:700">Sustain</div>
            <div style="font-size:20px;color:var(--accent)">$<span class="anim" data-month="280" data-package="1399">280</span></div>
            <div style="color:var(--muted)">Longer pathway support</div>
          </div>
        </div>

      </div>
    </section>

  </main>

  <footer style="padding:18px 24px;color:var(--muted)">
    <div>Questions? Email <a href="mailto:{{EMAIL}}" style="color:var(--muted)">{{EMAIL}}</a> or call {{PHONE}}</div>
    <div>Serving {{CITY}}, {{STATE}}</div>
  </footer>

  <script>
    // small comparator with animated numerics
    (function(){
      const btnMonth = document.getElementById('view-month');
      const btnPack = document.getElementById('view-package');
      const elems = document.querySelectorAll('.anim');

      function animate(el, start, end, dur){
        let t0 = null;
        const n = (t) => {
          if(!t0) t0 = t;
          const p = Math.min((t - t0)/dur,1);
          el.textContent = Math.round(start + (end - start)*p);
          if(p < 1) requestAnimationFrame(n);
        };
        requestAnimationFrame(n);
      }

      function setMode(mode){
        elems.forEach((el)=>{
          const target = parseInt(el.getAttribute(mode==='monthly'? 'data-month':'data-package'),10);
          const current = parseInt(el.textContent,10) || 0;
          animate(el,current,target,500);
        });
        btnMonth.style.background = mode==='monthly'? '#072126':'transparent';
        btnPack.style.background = mode==='package'? '#072126':'transparent';
      }

      btnMonth.addEventListener('click',()=>setMode('monthly'));
      btnPack.addEventListener('click',()=>setMode('package'));

      setMode('monthly');
    })();
